import{_ as t,o as a,c as o,aj as n}from"./chunks/framework.C6uXqnaX.js";const h=JSON.parse('{"title":"Custom build pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"en/ecosystem/custom-build-pipeline.md","filePath":"en/ecosystem/custom-build-pipeline.md"}'),i={name:"en/ecosystem/custom-build-pipeline.md"};function r(s,e,l,u,p,d){return a(),o("div",null,e[0]||(e[0]=[n('<h1 id="custom-build-pipeline" tabindex="-1">Custom build pipeline <a class="header-anchor" href="#custom-build-pipeline" aria-label="Permalink to &quot;Custom build pipeline&quot;">​</a></h1><p>When building an Angular app we strongly recommend you to use the Angular CLI to leverage its structure-dependent update functionality and build system abstraction. This way your projects benefit from the latest security, performance, and API improvements and transparent build improvements.</p><p>This page explores the <strong>rare use cases</strong> when you need a custom build pipeline that does not use the Angular CLI. All listed tools below are open source build plugins that are maintained by members of the Angular community. To learn more about their support model and maintenance status look at their documentation and GitHub repository URLs.</p><h2 id="when-should-you-use-a-custom-build-pipeline" tabindex="-1">When should you use a custom build pipeline? <a class="header-anchor" href="#when-should-you-use-a-custom-build-pipeline" aria-label="Permalink to &quot;When should you use a custom build pipeline?&quot;">​</a></h2><p>There are some niche use cases when you may want to maintain a custom build pipeline. For example:</p><ul><li>You have an existing app using a different toolchain and you’d like to add Angular to it</li><li>You’re strongly coupled to <a href="https://module-federation.io/" target="_blank" rel="noreferrer">module federation</a> and unable to adopt bundler-agnostic <a href="https://www.npmjs.com/package/@angular-architects/native-federation" target="_blank" rel="noreferrer">native federation</a></li><li>You’d like to create a short-lived experiment using your favorite build tool</li></ul><h2 id="what-are-the-options" tabindex="-1">What are the options? <a class="header-anchor" href="#what-are-the-options" aria-label="Permalink to &quot;What are the options?&quot;">​</a></h2><p>Currently, there are two well supported community tools that enable you to create a custom build pipeline with a <a href="https://www.npmjs.com/package/@analogjs/vite-plugin-angular" target="_blank" rel="noreferrer">Vite plugin</a> and <a href="https://www.npmjs.com/package/@nx/angular-rspack" target="_blank" rel="noreferrer">Rspack plugin</a>. Both of them use underlying abstractions that power the Angular CLI. They allow you to create a flexible build pipeline and require manual maintenance and no automated update experience.</p><h3 id="rspack" tabindex="-1">Rspack <a class="header-anchor" href="#rspack" aria-label="Permalink to &quot;Rspack&quot;">​</a></h3><p>Rspack is a Rust-based bundler that aims to provide compatibility with the webpack plugin ecosystem.</p><p>If your project is tightly coupled to the webpack ecosystem, heavily relying on a custom webpack configuration you can leverage Rspack to improve your build times.</p><p>You can find more about Angular Rspack on the project’s <a href="https://nx.dev/recipes/angular/rspack/introduction" target="_blank" rel="noreferrer">documentation website</a>.</p><h3 id="vite" tabindex="-1">Vite <a class="header-anchor" href="#vite" aria-label="Permalink to &quot;Vite&quot;">​</a></h3><p>Vite is a frontend build tool that aims to provide a faster and leaner development experience for modern web projects. Vite is also extensible through its plugin system that allows ecosystems to build integrations with Vite, such as Vitest for unit and browser testing, Storybook for authoring components in isolation, and more. The Angular CLI also uses Vite as its development server.</p><p>The <a href="https://www.npmjs.com/package/@analogjs/vite-plugin-angular" target="_blank" rel="noreferrer">AnalogJS Vite plugin for Angular</a> enables the adoption of Angular with a project or framework that uses or is built on top of Vite. This can consist of developing and building an Angular project with Vite directly, or adding Angular to an existing project or pipeline. One example is integrating Angular UI components into a documentation website using <a href="https://analogjs.org/docs/packages/astro-angular/overview" target="_blank" rel="noreferrer">Astro and Starlight</a>.</p><p>You can learn more about AnalogJS and how to use the plugin through its <a href="https://analogjs.org/docs/packages/vite-plugin-angular/overview" target="_blank" rel="noreferrer">documentation page</a>.</p>',16)]))}const m=t(i,[["render",r]]);export{h as __pageData,m as default};
